async def act(page):
    """
    From the current Orders / Sales grid page, apply a Purchased On (created) date range
    of 2021-05-01 -> 2022-03-31 and export the grid as CSV.

    This function assumes we are already on '/index.php/admin/sales_order/' (per the
    provided page state) and uses scoped get_by_role calls so clicks are unambiguous.
    """
    import asyncio
    from pathlib import Path

    out_filename = 'orders_2021-05-01_to_2022-03-31.csv'

    # Helper: read locator count safely
    async def count(locator):
        try:
            return await locator.count()
        except Exception:
            return 0

    # Find the Orders table by locating the table that has the header link "Order #"
    tables = page.get_by_role('table')
    tcount = await count(tables)
    orders_table = None
    for i in range(tcount):
        tbl = tables.nth(i)
        try:
            # scope by presence of the header link "Order #"
            if await tbl.get_by_role('link', name='Order #').count() > 0:
                orders_table = tbl
                break
        except Exception:
            continue

    if orders_table is None:
        raise RuntimeError('Orders table not found on page')

    # Within the orders table, find the Purchased On filter cell which contains the two date textboxes
    # The accessibility tree shows a cell whose name is exactly: "From: Date selector . To : Date selector ."
    # Use a substring match by searching for a cell that contains "From: Date selector" text.
    filter_cells = orders_table.get_by_role('cell')
    fc_count = await count(filter_cells)
    purchased_on_cell = None
    for i in range(fc_count):
        c = filter_cells.nth(i)
        try:
            txt = (await c.inner_text()) or ''
        except Exception:
            txt = ''
        if 'from: date selector' in txt.lower() and 'to' in txt.lower():
            purchased_on_cell = c
            break

    if purchased_on_cell is None:
        # As a fallback, try to find the cell whose accessible name contains "Purchased On"
        try:
            purchased_on_cell = orders_table.get_by_role('cell', name='Purchased On')
            if await count(purchased_on_cell) == 0:
                purchased_on_cell = None
        except Exception:
            purchased_on_cell = None

    if purchased_on_cell is None:
        raise RuntimeError('Could not locate the Purchased On filter cell with date inputs')

    # Inside that cell, find the two textboxes (From and To)
    textboxes = purchased_on_cell.get_by_role('textbox')
    tb_count = await count(textboxes)
    if tb_count < 2:
        raise RuntimeError('Expected two date textboxes in Purchased On filter cell, found %d' % tb_count)

    from_input = textboxes.nth(0)
    to_input = textboxes.nth(1)

    # Fill the desired date range. Use common MM/DD/YYYY format that Magento admin often accepts.
    from_date = '05/01/2021'
    to_date = '03/31/2022'

    await from_input.fill(from_date)
    await to_input.fill(to_date)

    # Click the Search button scoped to the same orders_table to apply filters
    # Use the full scoped path per guidance
    search_btn = None
    try:
        # Try to find a button named "Search" inside the orders table
        if await orders_table.get_by_role('button', name='Search').count() > 0:
            search_btn = orders_table.get_by_role('button', name='Search').nth(0)
    except Exception:
        search_btn = None

    if search_btn is not None:
        await search_btn.click()
        # Wait a short while for the grid to refresh
        await page.wait_for_load_state('networkidle')
        await asyncio.sleep(0.5)
    else:
        # If Search button wasn't found inside the table, try a page-level "Search" button
        page_search = page.get_by_role('button', name='Search')
        if await count(page_search) > 0:
            await page_search.nth(0).click()
            await page.wait_for_load_state('networkidle')
            await asyncio.sleep(0.5)
        else:
            # If there is no explicit Search button, assume filters auto-apply and continue
            await asyncio.sleep(0.5)

    # The top area shows an "Export to: CSV" combobox and an Export button inside a cell whose
    # accessible name is "Export to: CSV Export". Scope to that cell and click Export while
    # capturing the download.
    export_cell = None
    try:
        # Attempt to find a cell whose inner text includes 'Export to' within the orders_table
        cells = orders_table.get_by_role('cell')
        for i in range(await count(cells)):
            c = cells.nth(i)
            try:
                txt = (await c.inner_text()) or ''
            except Exception:
                txt = ''
            if 'export to' in txt.lower():
                export_cell = c
                break
    except Exception:
        export_cell = None

    if export_cell is None:
        # fallback: try to find a button named Export somewhere in the orders_table
        try:
            if await orders_table.get_by_role('button', name='Export').count() > 0:
                export_btn = orders_table.get_by_role('button', name='Export').nth(0)
            else:
                export_btn = None
        except Exception:
            export_btn = None

        if export_btn is None:
            raise RuntimeError('Could not find Export controls on the page')

        # Click and capture download
        async with page.expect_download() as dd:
            await export_btn.click()
        download = await dd.value
        out_path = Path(out_filename)
        await download.save_as(str(out_path))
        try:
            csv_text = out_path.read_text(encoding='utf-8')
        except Exception:
            csv_text = out_path.read_text(encoding='latin-1')
        return {'filename': str(out_path), 'csv': csv_text}

    # If we found the export_cell, find the Export button within it
    try:
        export_btns = export_cell.get_by_role('button')
        if await count(export_btns) == 0:
            # fallback to any Export button in the table
            if await orders_table.get_by_role('button', name='Export').count() > 0:
                export_btn = orders_table.get_by_role('button', name='Export').nth(0)
            else:
                raise RuntimeError('Export button not found')
        else:
            # prefer the button with name 'Export'
            found = None
            for i in range(await count(export_btns)):
                b = export_btns.nth(i)
                try:
                    txt = (await b.inner_text()) or ''
                except Exception:
                    txt = ''
                if 'export' in txt.lower():
                    found = b
                    break
            export_btn = found or export_btns.nth(0)
    except Exception as e:
        raise RuntimeError('Error locating Export button: %s' % (e,))

    # Click Export and save download
    async with page.expect_download() as dd:
        await export_btn.click()
    download = await dd.value
    out_path = Path(out_filename)
    await download.save_as(str(out_path))
    try:
        csv_text = out_path.read_text(encoding='utf-8')
    except Exception:
        csv_text = out_path.read_text(encoding='latin-1')

    return {'filename': str(out_path), 'csv': csv_text}

